    public function read():array{$c=$this->config();$month=gmdate('Y-m',intdiv($this->now(),1000));$u=$this->query('SELECT calls,blocked FROM jingo_weather_usage WHERE month=?',[$month])->fetch(PDO::FETCH_ASSOC);return ['enabled'=>$c['enabled'],'version'=>$c['version'],'keyConfigured'=>!empty($c['encryptedKey']),'month'=>$month,'calls'=>(int)($u['calls']??0),'blocked'=>(bool)($u['blocked']??false),'limit'=>self::LIMIT];}
    public function save(array $in,string $actor):array
