        if(array_diff(array_keys($in),['version','enabled','apiKey'])||!is_bool($in['enabled']??null)||!is_int($in['version']??null)||$in['version']<0||$in['version']>2147483646||array_key_exists('apiKey',$in)&&(!is_string($in['apiKey'])||!preg_match('/^[A-Za-z0-9_-]{0,128}$/D',trim($in['apiKey']))))throw new HttpError(400,'Kiểm tra cấu hình thời tiết.');
        $this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{if(!$this->query("SELECT id FROM jingo_catalog_locks WHERE id='catalog' FOR UPDATE")->fetchColumn())throw new HttpError(503,'Chưa cài khóa danh mục.');$old=$this->config();if($old['version']!==$in['version'])throw new HttpError(409,'Cấu hình đã thay đổi. Tải lại trước khi lưu.');$key=trim($in['apiKey']??'');$encrypted=$key!==''?(new SecretCipher($this->directory))->encrypt($key):($old['encryptedKey']??null);if($in['enabled']&&!$encrypted)throw new HttpError(400,'Nhập API Key WeatherAPI trước khi bật.');$data=['enabled'=>$in['enabled']];if($encrypted)$data['encryptedKey']=$encrypted;$this->query("INSERT INTO jingo_settings(id,data,version) VALUES ('weather',?,?) ON DUPLICATE KEY UPDATE data=VALUES(data),version=VALUES(version)",[json_encode($data,JSON_THROW_ON_ERROR),$in['version']+1]);$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$actor,'weather.settings','weather']);$this->db->commit();return $this->read();}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
