    private function request(string $key,string $coords):array
    {
        if($this->fetch)return ($this->fetch)($key,$coords);
        if(!function_exists('curl_init'))throw new RuntimeException('Weather unavailable');$url='https://api.weatherapi.com/v1/forecast.json?'.http_build_query(['key'=>$key,'q'=>$coords,'days'=>3,'aqi'=>'no','alerts'=>'no']);$c=curl_init($url);$body='';curl_setopt_array($c,[CURLOPT_FOLLOWLOCATION=>false,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_TIMEOUT=>5,CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_WRITEFUNCTION=>static function($c,string $chunk)use(&$body):int{if(strlen($body)+strlen($chunk)>1048576)return 0;$body.=$chunk;return strlen($chunk);}]);try{$ok=curl_exec($c);$status=(int)curl_getinfo($c,CURLINFO_RESPONSE_CODE);if($ok===false||$status>=300&&$status<400)throw new RuntimeException('Weather unavailable');$raw=json_decode($body,true,64,JSON_THROW_ON_ERROR);if(!is_array($raw))throw new RuntimeException('Weather unavailable');return ['ok'=>$status>=200&&$status<300,'data'=>$raw];}finally{curl_close($c);}
