    private function expose(?array $data,int $fetched,int $now,array $place,string $lang):?array
    {
        if(!$data||$now-$fetched>14400000||$now-(int)(strtotime($data['updatedAt'])*1000)>14400000)return null;$days=array_values(array_filter($data['days'],fn($d)=>$d['date']>=WeatherRules::today($now)));if(!$days)return null;return array_replace($data,['place'=>$lang==='en'?(($place['englishName']??'')?:$place['name']):$place['name'],'stale'=>$now-$fetched>=3600000,'days'=>array_map(fn($d)=>$d+['advice'=>WeatherRules::advice($d,$lang)],$days)]);
    }
    public function get(string $id,string $lang='vi'):?array
    {
        if(!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/iD',$id))return null;$config=$this->config();if(!$config['enabled']||empty($config['encryptedKey']))return null;$nodes=array_column((new Destinations($this->db))->list(),null,'id');$place=$nodes[$id]??null;$seen=[];while($place&&empty($place['coordinates'])){if(isset($seen[$place['id']]))return null;$seen[$place['id']]=true;$place=$nodes[$place['parentId']]??null;}if(!$place)return null;$coords=number_format($place['coordinates']['lat'],4,'.','').','.number_format($place['coordinates']['lon'],4,'.','');$now=$this->now();$month=gmdate('Y-m',intdiv($now,1000));$this->query('INSERT IGNORE INTO jingo_weather_usage(month) VALUES (?)',[$month]);$usage=$this->query('SELECT calls,blocked FROM jingo_weather_usage WHERE month=?',[$month])->fetch(PDO::FETCH_ASSOC);if($usage['blocked']||$usage['calls']>=self::LIMIT)return null;$this->query('INSERT IGNORE INTO jingo_weather_cache(id) VALUES (?)',[$coords]);$row=$this->query('SELECT data,fetched_at,next_attempt FROM jingo_weather_cache WHERE id=?',[$coords])->fetch(PDO::FETCH_ASSOC);$old=$row['data']?json_decode($row['data'],true,512,JSON_THROW_ON_ERROR):null;$cached=fn()=>$this->expose($old,(int)$row['fetched_at'],$now,$place,$lang);if((int)$row['next_attempt']>$now)return $cached();if(!$this->query('UPDATE jingo_weather_cache SET next_attempt=? WHERE id=? AND next_attempt<=?',[$now+15000,$coords,$now])->rowCount())return $cached();if(!$this->query('UPDATE jingo_weather_usage SET calls=calls+1 WHERE month=? AND calls<? AND blocked=FALSE',[$month,self::LIMIT])->rowCount())return null;
        try{$response=$this->request((new SecretCipher($this->directory))->decrypt($config['encryptedKey']),$coords);if(!$response['ok']){if(($response['data']['error']['code']??null)===2007){$this->query('UPDATE jingo_weather_usage SET blocked=TRUE WHERE month=?',[$month]);return null;}throw new RuntimeException('Weather unavailable');}$data=WeatherRules::normalize($response['data'],$now);$this->query('UPDATE jingo_weather_cache SET data=?,fetched_at=?,next_attempt=? WHERE id=? AND next_attempt=?',[json_encode($data,JSON_THROW_ON_ERROR),$now,$now+3600000,$coords,$now+15000]);return $this->expose($data,$now,$now,$place,$lang);}catch(Throwable){return $cached();}finally{$this->query('UPDATE jingo_weather_cache SET next_attempt=? WHERE id=? AND next_attempt=?',[$now+3600000,$coords,$now+15000]);}
    }
}
